            if (\gold.rob_instance.C_valid ) begin 

                        if(\gate.C_mem_valid == 1 && \gold.C_mem_valid == 1 && \gate.C_mem_rdwt == 1 && \gold.C_mem_rdwt == 1 &&   \gate.C_mem_addr != \gold.C_mem_addr ) begin
                            invalid_program <= 1;
                        end


                        if(\gate.C_is_br == 1 && \gold.C_is_br == 1 &&   \gate.C_taken != \gold.C_taken ) begin
                            invalid_program <= 1;
                        end

            end

        end else if (!gate_stuttering_signal && gold_stuttering_signal ) begin 

            if (\gate.rob_instance.C_valid ) begin 

                        if(\gate.C_mem_valid == 1 && \gold.C_mem_valid == 1 && \gate.C_mem_rdwt == 1 && \gold.C_mem_rdwt == 1 &&   \gate.C_mem_addr != \gold.C_mem_addr ) begin
                            invalid_program <= 1;
                        end


                        if(\gate.C_is_br == 1 && \gold.C_is_br == 1 &&   \gate.C_taken != \gold.C_taken ) begin
                            invalid_program <= 1;
                        end

            end

        end

    end
end

assume  (invalid_program == 0 );


    wire trg_equiv = !commit_deviation;

    reg [6: 0]  bound = 35;

    always @ (posedge in_clk) begin
        if (bound > 0 && !state_trg_equiv) begin
            bound <= bound - 1;
        end
    end

    // update the states for verification
    reg state_trg_equiv = 1;
    always @ (posedge in_clk) begin
            state_trg_equiv <= state_trg_equiv && trg_equiv;
    end

    wire fin_state_trg_equiv = ( bound > 0 || gate_stuttering_signal || gold_stuttering_signal) ||  state_trg_equiv ;

    assert  (fin_state_trg_equiv);

endmodule
